INSERT OR IGNORE INTO venues (id, slug, name, category, category_label, short_description, description, image_url, gallery, address, city, province, capacity, year_built, amenities, features, how_to_get, phone, email, website) VALUES ('venue-estadio-quisqueya', 'estadio-quisqueya', 'Estadio Quisqueya Juan Marichal', 'estadio', 'Estadio de Béisbol', 'El templo del béisbol invernal dominicano (LIDOM). Sede histórica de los Tigres del Licey y Leones del Escogido. Además de albergar la Serie del Caribe, su amplio campo se transforma para megaconciertos multitudinarios de artistas internacionales.', 'El templo del béisbol invernal dominicano (LIDOM). Sede histórica de los Tigres del Licey y Leones del Escogido. Además de albergar la Serie del Caribe, su amplio campo se transforma para megaconciertos multitudinarios de artistas internacionales.', 'https://images.unsplash.com/photo-1579952363873-27f3bade9f55?w=1920&h=800&fit=crop', NULL, 'Av. Tiradentes esq. San Cristóbal, Santo Domingo D.N.', 'Ensanche La Fe, Santo Domingo', 'Santo Domingo', 14400, 1955, '["Palcos VIP Climatizados","Estacionamiento Vigilado","Restaurantes & Bares","Tiendas Oficiales","WiFi","Acceso Inclusivo"]', '["Sede de Tigres del Licey","Sede de Leones del Escogido"]', '{"byMetro":"Estación Pedro Mir o Casandra Damirón (Línea 1/2 con enlace de taxi/bus)","byBus":"Corredor Tiradentes y Rutas de la Av. San Cristóbal","byCar":"Acceso directo por Av. John F. Kennedy y Av. Tiradentes. Parqueos internos y perímetros vigilados.","parking":"Más de 1,200 espacios de aparcamiento disponible con tarifa fija en días de evento."}', '+1 (809) 567-6371', NULL, 'https://lidom.com');
INSERT OR IGNORE INTO venues (id, slug, name, category, category_label, short_description, description, image_url, gallery, address, city, province, capacity, year_built, amenities, features, how_to_get, phone, email, website) VALUES ('venue-estadio-cibao', 'estadio-cibao', 'Estadio Cibao', 'estadio', 'Estadio de Béisbol', 'Conocido como ''El Valle de la Muerte'', es el estadio con mayor capacidad de República Dominicana y casa de las Águilas Cibaeñas. Es célebre por su apasionada fanaticada y su uso constante para espectáculos multitudinarios y festivales del Cibao.', 'Conocido como ''El Valle de la Muerte'', es el estadio con mayor capacidad de República Dominicana y casa de las Águilas Cibaeñas. Es célebre por su apasionada fanaticada y su uso constante para espectáculos multitudinarios y festivales del Cibao.', 'https://images.unsplash.com/photo-1569863959165-56dae551d4fc?w=1920&h=800&fit=crop', NULL, 'Av. Imbert, Sector Las Colinas, Santiago', 'Santiago de los Caballeros', 'Santiago', 18077, 1958, '["Palcos Ejecutivos","Gradas VIP","Zona Gastronómica Cibaeña","Parqueo Asfaltado","Seguridad Privada"]', '["Sede de Águilas Cibaeñas"]', '{"byBus":"Rutas de concho A, B y F desde el Centro Histórico de Santiago","byCar":"Fácil acceso desde la Autopista Duarte ingresando por la Avenida Imbert."}', '+1 (809) 575-4310', NULL, 'https://aguilas.com.do');
INSERT OR IGNORE INTO venues (id, slug, name, category, category_label, short_description, description, image_url, gallery, address, city, province, capacity, year_built, amenities, features, how_to_get, phone, email, website) VALUES ('venue-estadio-olimpico-felix-sanchez', 'estadio-olimpico-felix-sanchez', 'Estadio Olímpico Félix Sánchez', 'estadio', 'Estadio Olímpico & Multiuso', 'El recinto de espectáculos y eventos deportivos de mayor escala en la historia del país. Ha sido escenario de los Juegos Panamericanos 2003, Copas Mundiales FIFA Femeninas Sub-17, el histórico Festival Presidente de Música Latina y conciertos de estrellas globales.', 'El recinto de espectáculos y eventos deportivos de mayor escala en la historia del país. Ha sido escenario de los Juegos Panamericanos 2003, Copas Mundiales FIFA Femeninas Sub-17, el histórico Festival Presidente de Música Latina y conciertos de estrellas globales.', 'https://images.unsplash.com/photo-1540747913346-19e32dc3e97e?w=1920&h=800&fit=crop', NULL, 'Av. Máximo Gómez esq. 27 de Febrero, Santo Domingo D.N.', 'Centro Olímpico Juan Pablo Duarte, Santo Domingo', 'Santo Domingo', 50000, 1974, '["Pista Atlética Sintética","Gramado Olímpico FIFA","Cabinas de Transmisión Internacional","Múltiples Accesos Peatonales","Conexión a Red de Metro"]', NULL, '{"byMetro":"Estación Juan Bosch o Juan Pablo Duarte (cruce Líneas 1 y 2 a pocos pasos)","byBus":"Corredor 27 de Febrero y Corredor Máximo Gómez","byCar":"Ingresos por Av. 27 de Febrero, Ortega y Gasset y Máximo Gómez."}', NULL, NULL, NULL);
INSERT OR IGNORE INTO venues (id, slug, name, category, category_label, short_description, description, image_url, gallery, address, city, province, capacity, year_built, amenities, features, how_to_get, phone, email, website) VALUES ('venue-palacio-deportes-virgilio-travieso', 'palacio-deportes-virgilio-travieso', 'Palacio de los Deportes Virgilio Travieso Soto (''La Media Naranja'')', 'arena', 'Arena Techada & Coliseo', 'Icónica arena cubierta con cúpula naranja, epicentro del Baloncesto Superior del Distrito Nacional (TBS), partidos de la Selección Dominicana de Baloncesto (''Los Quisqueyanos''), voleibol internacional de Las Reinas del Caribe, y conciertos bajo techo con climatización central.', 'Icónica arena cubierta con cúpula naranja, epicentro del Baloncesto Superior del Distrito Nacional (TBS), partidos de la Selección Dominicana de Baloncesto (''Los Quisqueyanos''), voleibol internacional de Las Reinas del Caribe, y conciertos bajo techo con climatización central.', 'https://images.unsplash.com/photo-1504450758481-7338eba7524a?w=1920&h=800&fit=crop', NULL, 'Centro Olímpico Juan Pablo Duarte, Av. 27 de Febrero, Santo Domingo', 'Centro Olímpico, Santo Domingo', 'Santo Domingo', 8300, 1974, '["Climatización Integral A/C","Tabloncillo de Madera Certificado FIBA","Pantalla Central LED 360","Palcos Presidenciales","Camerinos de Nivel Olímpico"]', NULL, '{"byMetro":"Estación Juan Pablo Duarte (L1 y L2)","byCar":"Parqueo vigilado dentro del complejo del Centro Olímpico."}', NULL, NULL, NULL);
INSERT OR IGNORE INTO venues (id, slug, name, category, category_label, short_description, description, image_url, gallery, address, city, province, capacity, year_built, amenities, features, how_to_get, phone, email, website) VALUES ('venue-arena-del-cibao', 'arena-del-cibao', 'Gran Arena del Cibao Dr. Oscar Gobaira', 'arena', 'Arena Multiuso Climatizada', 'Moderna arena techada de clase mundial en el corazón de Santiago. Sede del Baloncesto Superior de Santiago (ABASACA), veladas de boxeo titular, torneos de voleibol y presentaciones teatrales y musicales de artistas nacionales e internacionales.', 'Moderna arena techada de clase mundial en el corazón de Santiago. Sede del Baloncesto Superior de Santiago (ABASACA), veladas de boxeo titular, torneos de voleibol y presentaciones teatrales y musicales de artistas nacionales e internacionales.', 'https://images.unsplash.com/photo-1519766304817-4f37bda74a29?w=1920&h=800&fit=crop', NULL, 'Av. Salvador Estrella Sadhalá esq. Av. Imbert, Santiago', 'Santiago de los Caballeros', 'Santiago', 8768, 1979, '["Aire Acondicionado Central","Asientos Ergonómicos","Piso de Parquet Flotante","Sonido Line-Array","Cafeterías & Lounge"]', NULL, '{"byCar":"Sobre la Av. Estrella Sadhalá frente al complejo deportivo municipal."}', NULL, NULL, NULL);
INSERT OR IGNORE INTO venues (id, slug, name, category, category_label, short_description, description, image_url, gallery, address, city, province, capacity, year_built, amenities, features, how_to_get, phone, email, website) VALUES ('venue-teeth-of-the-dog', 'teeth-of-the-dog', 'Teeth of the Dog (Casa de Campo)', 'golf', 'Campo de Golf de Campeonato', 'La obra cumbre del maestro Pete Dye y consagrado unánimemente como el campo de golf número 1 del Caribe y top 50 mundial. Con 7 hoyos excavados directamente contra los arrecifes y acantilados coralinos del Mar Caribe. Sede de torneos internacionales como el Latin America Amateur ', 'La obra cumbre del maestro Pete Dye y consagrado unánimemente como el campo de golf número 1 del Caribe y top 50 mundial. Con 7 hoyos excavados directamente contra los arrecifes y acantilados coralinos del Mar Caribe. Sede de torneos internacionales como el Latin America Amateur Championship (LAAC) clasificatorio al Masters de Augusta.', 'https://images.unsplash.com/photo-1535131749006-b7f58c99034b?w=1920&h=800&fit=crop', NULL, 'Casa de Campo Resort & Villas, Carretera La Romana - Higuey', 'La Romana', 'La Romana', 1872, 1971, '["Pro Shop Titleist / FootJoy","Driving Range con TrackMan","Restaurante 19th Hole","Servicio de Caddie Profesional","Carritos de Golf Eléctricos con GPS"]', '["18 hoyos, par 72","Diseño: Pete Dye","Green fee: US$ 395 - US$ 495"]', '{"byCar":"A 5 minutos del Aeropuerto Internacional de La Romana (LRM) y a 45 min de Punta Cana por la Autovía del Este."}', '+1 (809) 523-8115', NULL, 'https://casadecampo.com.do');
INSERT OR IGNORE INTO venues (id, slug, name, category, category_label, short_description, description, image_url, gallery, address, city, province, capacity, year_built, amenities, features, how_to_get, phone, email, website) VALUES ('venue-corales-golf-club', 'corales-golf-club', 'Corales Golf Club (Puntacana Resort)', 'golf', 'Campo de Golf PGA Tour Venue', 'Sede oficial del prestigioso PGA TOUR Corales Puntacana Championship. Diseñado por Tom Fazio, este campo culmina con el ''Codo del Diablo'' (Devil''s Elbow), un trío final de hoyos dramáticos tallados a lo largo de acantilados oceánicos del Atlántico.', 'Sede oficial del prestigioso PGA TOUR Corales Puntacana Championship. Diseñado por Tom Fazio, este campo culmina con el ''Codo del Diablo'' (Devil''s Elbow), un trío final de hoyos dramáticos tallados a lo largo de acantilados oceánicos del Atlántico.', 'https://images.unsplash.com/photo-1587174486073-ae5e5cff23aa?w=1920&h=800&fit=crop', NULL, 'Puntacana Resort & Club, Punta Cana', 'Punta Cana', 'La Altagracia', 1872, 2010, '["Clubhouse Exclusivo con Terraza Marítima","Pro Shop Oficial PGA TOUR","Academia de Golf","Locker Rooms de Lujo"]', '["18 hoyos, par 72","Diseño: Tom Fazio","Green fee: US$ 350 - US$ 450"]', '{"byCar":"A solo 10 minutos del Aeropuerto Internacional de Punta Cana (PUJ)."}', NULL, NULL, NULL);
INSERT OR IGNORE INTO venues (id, slug, name, category, category_label, short_description, description, image_url, gallery, address, city, province, capacity, year_built, amenities, features, how_to_get, phone, email, website) VALUES ('venue-punta-espada-golf-club', 'punta-espada-golf-club', 'Punta Espada Golf Club (Cap Cana)', 'golf', 'Campo Jack Nicklaus Signature', 'Catalogado recurrentemente como uno de los mejores campos de golf de México y el Caribe por Golf Digest. Ocho de sus hoyos discurren directamente junto al mar, invitando a tiros sobre bahías turquesas.', 'Catalogado recurrentemente como uno de los mejores campos de golf de México y el Caribe por Golf Digest. Ocho de sus hoyos discurren directamente junto al mar, invitando a tiros sobre bahías turquesas.', 'https://images.unsplash.com/photo-1593111774240-d529f12cf4bb?w=1920&h=800&fit=crop', NULL, 'Cap Cana Resort, Punta Cana', 'Cap Cana', 'La Altagracia', 1872, 2006, '["Clubhouse con Vistas Panorámicas","Restaurante Hoyo 19 Gourmet","Flota de Carritos con GPS de Alta Definición"]', '["18 hoyos, par 72","Diseño: Jack Nicklaus","Green fee: US$ 380 - US$ 480"]', '{"byCar":"Ingresando por el portón principal de Cap Cana hacia el sector Punta Espada."}', NULL, NULL, NULL);
INSERT OR IGNORE INTO venues (id, slug, name, category, category_label, short_description, description, image_url, gallery, address, city, province, capacity, year_built, amenities, features, how_to_get, phone, email, website) VALUES ('venue-teatro-nacional-eduardo-brito', 'teatro-nacional-eduardo-brito', 'Teatro Nacional Eduardo Brito', 'teatro', 'Teatro Nacional & Bellas Artes', 'La máxima casa del arte escénico y la cultura de la República Dominicana. Diseñado con una acústica prodigiosa por el arquitecto Teófilo Carbonell, cuenta con la emblemática Sala Principal Carlos Piantini, la Sala Ravelo y la Sala Aida Bonnelly. Sede de óperas, ballets clásicos, ', 'La máxima casa del arte escénico y la cultura de la República Dominicana. Diseñado con una acústica prodigiosa por el arquitecto Teófilo Carbonell, cuenta con la emblemática Sala Principal Carlos Piantini, la Sala Ravelo y la Sala Aida Bonnelly. Sede de óperas, ballets clásicos, la Orquesta Sinfónica Nacional, los Premios Soberano y obras de teatro internacionales.', 'https://images.unsplash.com/photo-1507676184212-d03ab07a01bf?w=1920&h=800&fit=crop', NULL, 'Av. Máximo Gómez #35, Plaza de la Cultura Juan Pablo Duarte, D.N.', 'Plaza de la Cultura, Santo Domingo', 'Santo Domingo', 1589, 1973, '["Foyer de Mármol & Esculturas","Fila VIP & Palcos Presidenciales","Foso Hidráulico para Orquesta","Cafetería Cultural","Parqueo en Plaza de la Cultura"]', NULL, '{"byMetro":"Estación Casandra Damirón (Línea 1) ubicada literalmente en la entrada del Teatro","byCar":"Acceso vehicular por la Avenida Máximo Gómez con parqueo vigilado."}', '+1 (809) 687-3191', NULL, 'https://teatronacional.gob.do');
INSERT OR IGNORE INTO venues (id, slug, name, category, category_label, short_description, description, image_url, gallery, address, city, province, capacity, year_built, amenities, features, how_to_get, phone, email, website) VALUES ('venue-anfiteatro-altos-de-chavon', 'anfiteatro-altos-de-chavon', 'Anfiteatro Griego de Altos de Chavón', 'teatro', 'Anfiteatro de Piedra al Aire Libre', 'Inaugurado con el célebre concierto ''Concert for the Americas'' de Frank Sinatra y Buddy Rich en 1982. Este imponente anfiteatro de piedra coralina de estilo romano-griego con vista al río Chavón ha acogido leyendas como Sting, Elton John, Andrea Bocelli, Bad Bunny y Juan Luis Gue', 'Inaugurado con el célebre concierto ''Concert for the Americas'' de Frank Sinatra y Buddy Rich en 1982. Este imponente anfiteatro de piedra coralina de estilo romano-griego con vista al río Chavón ha acogido leyendas como Sting, Elton John, Andrea Bocelli, Bad Bunny y Juan Luis Guerra.', 'https://images.unsplash.com/photo-1465847899084-d164df4dedc6?w=1920&h=800&fit=crop', NULL, 'Altos de Chavón, Casa de Campo, La Romana', 'Altos de Chavón, La Romana', 'La Romana', 5000, 1982, '["Vistas al Valle del Río Chavón","Pueblo Medieval de Piedra con Galerías","Restaurantes & Bares Exclusivos","Seguridad de Clase Mundial"]', NULL, '{"byCar":"Dentro del complejo Casa de Campo Resort, siguiendo señalizaciones hacia la Villa Cultural de Altos de Chavón."}', NULL, NULL, NULL);
INSERT OR IGNORE INTO venues (id, slug, name, category, category_label, short_description, description, image_url, gallery, address, city, province, capacity, year_built, amenities, features, how_to_get, phone, email, website) VALUES ('venue-centro-convenciones-hotel-jaragua', 'centro-convenciones-hotel-jaragua', 'Salón La Fiesta & Centro de Convenciones Renaissance Jaragua', 'centro_convenciones', 'Salón de Gala & Convenciones', 'Uno de los salones más legendarios de la capital dominicana. El Salón La Fiesta ha sido el hogar histórico de las grandes fiestas de fin de año, cumbres corporativas MICE, congresos médicos y recepciones nupciales de alta sociedad en el Malecón.', 'Uno de los salones más legendarios de la capital dominicana. El Salón La Fiesta ha sido el hogar histórico de las grandes fiestas de fin de año, cumbres corporativas MICE, congresos médicos y recepciones nupciales de alta sociedad en el Malecón.', 'https://images.unsplash.com/photo-1511578314322-379afb476865?w=1920&h=800&fit=crop', NULL, 'Av. George Washington #367, Malecón, Santo Domingo', 'Malecón de Santo Domingo', 'Santo Domingo', 1200, 1988, '["Banquete y Catering 5 Estrellas","División Modular en Salones","Equipos Audiovisuales de Punta","Valet Parking","Alojamiento Hotelero Integrado"]', NULL, '{"byCar":"Frente al Mar Caribe sobre la Av. George Washington con servicio de Valet Parking propio."}', '+1 (809) 221-2222', NULL, 'https://marriott.com');
INSERT OR IGNORE INTO venues (id, slug, name, category, category_label, short_description, description, image_url, gallery, address, city, province, capacity, year_built, amenities, features, how_to_get, phone, email, website) VALUES ('venue-convention-center-barcelo-bavaro', 'convention-center-barcelo-bavaro', 'Barceló Bávaro Grand Resort Convention Center', 'centro_convenciones', 'Centro de Convenciones Resort', 'El centro de convenciones más grande y moderno de toda la República Dominicana y el Caribe insular. Cuenta con 11,500 m² de espacio flexible dividido en 13 salas multifuncionales con tecnología de última generación para congresos globales y ferias turísticas como DATE.', 'El centro de convenciones más grande y moderno de toda la República Dominicana y el Caribe insular. Cuenta con 11,500 m² de espacio flexible dividido en 13 salas multifuncionales con tecnología de última generación para congresos globales y ferias turísticas como DATE.', 'https://images.unsplash.com/photo-1587825140708-dfaf72ae4b04?w=1920&h=800&fit=crop', NULL, 'Carretera Bávaro Km 1, Playa Bávaro', 'Playa Bávaro, Punta Cana', 'La Altagracia', 5000, 2011, '["13 Salas Modulares","Capacidad hasta 5,000 delegados","Alta Gastronomía Internacional","Helipuerto Cercano","A pie de Playa"]', NULL, '{"byCar":"A 20 minutos del Aeropuerto Internacional de Punta Cana en el complejo Barceló Bávaro."}', NULL, NULL, NULL);
INSERT OR IGNORE INTO venues (id, slug, name, category, category_label, short_description, description, image_url, gallery, address, city, province, capacity, year_built, amenities, features, how_to_get, phone, email, website) VALUES ('venue-agora-mall-atrio', 'agora-mall-atrio', 'Atrio Central & Jardín Ágora Mall', 'mall', 'Centro Comercial & Atrio de Eventos', 'El primer centro comercial ecológico certificado LEED Gold de Centroamérica y el Caribe. Su imponente Atrio Central de cuádruple altura y cúpula de cristal transparente es el epicentro urbano de ferias de emprendimiento (''El Mercadito de Ágora''), exhibiciones de arte, lanzamiento', 'El primer centro comercial ecológico certificado LEED Gold de Centroamérica y el Caribe. Su imponente Atrio Central de cuádruple altura y cúpula de cristal transparente es el epicentro urbano de ferias de emprendimiento (''El Mercadito de Ágora''), exhibiciones de arte, lanzamientos de productos y conciertos corales.', 'https://images.unsplash.com/photo-1567449303078-57ad995bd301?w=1920&h=800&fit=crop', NULL, 'Av. John F. Kennedy esq. Av. Abraham Lincoln, Santo Domingo', 'Piantini, Santo Domingo', 'Santo Domingo', 1500, 2012, '["Aire Acondicionado","4 Niveles de Parqueo Subterráneo","Zona Gastronómica ''El Jardín''","Seguridad Biométrica","Acceso Directo al Metro"]', NULL, '{"byMetro":"Estación Pedro Mir (Línea 2) con salida peatonal inmediata frente a Ágora Mall.","byCar":"Entradas vehiculares por la Av. John F. Kennedy y Av. Abraham Lincoln."}', '+1 (809) 472-2000', NULL, 'https://agora.com.do');
INSERT OR IGNORE INTO venues (id, slug, name, category, category_label, short_description, description, image_url, gallery, address, city, province, capacity, year_built, amenities, features, how_to_get, phone, email, website) VALUES ('venue-blue-mall-punta-cana', 'blue-mall-punta-cana', 'Anfiteatro de Aguas & Plaza BlueMall Punta Cana', 'mall', 'Lifestyle Mall & Anfiteatro', 'El shopping mall más sofisticado del Caribe Oriental. Cuenta con un innovador anfiteatro al aire libre con fuentes danzantes y espectáculos de luces, donde se realizan festivales de jazz, desfiles de moda de verano y catas gastronómicas.', 'El shopping mall más sofisticado del Caribe Oriental. Cuenta con un innovador anfiteatro al aire libre con fuentes danzantes y espectáculos de luces, donde se realizan festivales de jazz, desfiles de moda de verano y catas gastronómicas.', 'https://images.unsplash.com/photo-1555529669-e69e7aa0ba9a?w=1920&h=800&fit=crop', NULL, 'Boulevard Turístico del Este esq. Carretera Juanillo, Punta Cana', 'Punta Cana', 'La Altagracia', 2000, 2017, '["Fuentes Danzantes Iluminadas","Restaurantes de Lujo con Terrazas","Tiendas de Diseñador","Parqueo Gratuito"]', NULL, '{"byCar":"A 3 minutos del Aeropuerto de Punta Cana sobre el Boulevard Turístico del Este."}', '+1 (809) 784-4000', NULL, 'https://bluemallpuntacana.com.do');
